package config

import (
	"os"
	"strings"
	"testing"
)

// DEVDESK-210 step 6: app.when_unfocused, "pause" (default) or "run".

func TestWhenUnfocusedTable(t *testing.T) {
	tests := []struct {
		name      string
		in        string
		effective string
		runs      bool
		valid     bool
		warn      bool
	}{
		{"absent", "", WhenUnfocusedPause, false, true, false},
		{"pause", "pause", WhenUnfocusedPause, false, true, false},
		{"run", "run", WhenUnfocusedRun, true, true, false},
		{"unknown", "sleep", WhenUnfocusedPause, false, false, true},
		{"case matters", "Run", WhenUnfocusedPause, false, false, true},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			isolateMotionHome(t)
			buf := captureLog(t)
			cfg := Default()
			cfg.App.WhenUnfocused = tc.in
			if err := applyDefaults(cfg); err != nil {
				t.Fatalf("applyDefaults: %v", err)
			}
			if cfg.App.WhenUnfocused != tc.in {
				t.Errorf("WhenUnfocused = %q, want %q (kept as read)", cfg.App.WhenUnfocused, tc.in)
			}
			if got := cfg.App.EffectiveWhenUnfocused(); got != tc.effective {
				t.Errorf("EffectiveWhenUnfocused = %q, want %q", got, tc.effective)
			}
			if got := cfg.App.RunsWhenUnfocused(); got != tc.runs {
				t.Errorf("RunsWhenUnfocused = %v, want %v", got, tc.runs)
			}
			if got := cfg.App.WhenUnfocusedValid(); got != tc.valid {
				t.Errorf("WhenUnfocusedValid = %v, want %v", got, tc.valid)
			}
			want := `WARN [config] app.when_unfocused "` + tc.in + `" is not pause or run, pausing`
			if got := strings.Contains(buf.String(), want); got != tc.warn {
				t.Errorf("WARN logged = %v, want %v; log: %q", got, tc.warn, buf.String())
			}
		})
	}
}

func TestWhenUnfocusedConstantsAndSet(t *testing.T) {
	if WhenUnfocusedPause != "pause" || WhenUnfocusedRun != "run" || DefaultWhenUnfocused != WhenUnfocusedPause {
		t.Fatalf("constants: %q %q %q", WhenUnfocusedPause, WhenUnfocusedRun, DefaultWhenUnfocused)
	}
	got := WhenUnfocusedModes()
	if len(got) != 2 || got[0] != WhenUnfocusedPause || got[1] != WhenUnfocusedRun {
		t.Errorf("WhenUnfocusedModes() = %v, want [pause run]", got)
	}
}

func TestWhenUnfocusedDefaultDoesNotSetItself(t *testing.T) {
	isolateMotionHome(t)
	cfg := Default()
	if cfg.App.RunsWhenUnfocused() {
		t.Error("Default() must pause when unfocused")
	}
	if cfg.App.WhenUnfocused != "" {
		t.Errorf("Default().App.WhenUnfocused = %q, want empty (absent stays absent)", cfg.App.WhenUnfocused)
	}
}

func TestWhenUnfocusedValidValueRoundTrips(t *testing.T) {
	loaded, reloaded, saved := roundTrip(t, "app:\n  when_unfocused: run\n")
	if !loaded.App.RunsWhenUnfocused() || !reloaded.App.RunsWhenUnfocused() {
		t.Error("run must survive load, save and reload")
	}
	if !strings.Contains(saved, "when_unfocused: run") {
		t.Errorf("saved file lost when_unfocused: run:\n%s", saved)
	}
}

func TestWhenUnfocusedAbsentKeyStaysAbsentOnSave(t *testing.T) {
	loaded, reloaded, saved := roundTrip(t, "app:\n  gauge_glyph: block\n")
	if loaded.App.WhenUnfocused != "" || reloaded.App.WhenUnfocused != "" {
		t.Errorf("WhenUnfocused = %q / %q, want empty", loaded.App.WhenUnfocused, reloaded.App.WhenUnfocused)
	}
	if strings.Contains(saved, "when_unfocused") {
		t.Errorf("saved file gained a when_unfocused key:\n%s", saved)
	}
}

func TestWhenUnfocusedInvalidValueSurvivesLoadAndSave(t *testing.T) {
	buf := captureLog(t)
	loaded, reloaded, _ := roundTrip(t, "app:\n  when_unfocused: sleep\n")
	if loaded.App.WhenUnfocused != "sleep" || reloaded.App.WhenUnfocused != "sleep" {
		t.Errorf("loaded=%q reloaded=%q, want sleep kept", loaded.App.WhenUnfocused, reloaded.App.WhenUnfocused)
	}
	if loaded.App.WhenUnfocusedValid() || loaded.App.RunsWhenUnfocused() {
		t.Error("an invalid value must be invalid and pause")
	}
	if !strings.Contains(buf.String(), `WARN [config] app.when_unfocused "sleep" is not pause or run, pausing`) {
		t.Errorf("missing WARN, log: %q", buf.String())
	}
}

func TestWhenUnfocusedListFailsTheLoad(t *testing.T) {
	isolateMotionHome(t)
	if err := EnsureConfigDir(); err != nil {
		t.Fatal(err)
	}
	path, err := GetContextPath("wutest")
	if err != nil {
		t.Fatal(err)
	}
	if err := writeFile(path, "app:\n  when_unfocused: [run]\n"); err != nil {
		t.Fatal(err)
	}
	if _, err := LoadContext("wutest"); err == nil {
		t.Error("a list for app.when_unfocused must make the load fail, like the other app.* keys")
	}
}

func writeFile(path, body string) error { return os.WriteFile(path, []byte(body), 0o600) }
package app

import (
	"testing"

	tea "charm.land/bubbletea/v2"

	"github.com/anthnel/devdesk/internal/command"
	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/shared"
	"github.com/anthnel/devdesk/internal/ui/configuration"
	"github.com/anthnel/devdesk/internal/ui/testutil"
)

// ── DEVDESK-210 step 6: app.when_unfocused ──────────────────────────────────

func policyConfig(v string) *config.Config {
	cfg := testConfig()
	cfg.App.WhenUnfocused = v
	return cfg
}

// runPolicyRouter is a blink router whose policy was set to run through the
// router's own entry point (applyWhenUnfocused, called by handleConfigSaved
// and the context switch).
func runPolicyRouter(t *testing.T) (*App, *blinkView) {
	t.Helper()
	a, v, _ := blinkRouter(t, true)
	_ = a.applyWhenUnfocused(policyConfig(config.WhenUnfocusedRun))
	return a, v
}

func TestRunPolicyReachesTheRouterOnSaveAndContextSwitch(t *testing.T) {
	for name, apply := range applyBy {
		t.Run(name, func(t *testing.T) {
			a := router(t, &fakeView{})
			apply(a, policyConfig(config.WhenUnfocusedRun))
			// Views were rebuilt: install the one under observation now.
			v := &fakeView{}
			a.currentView = command.ViewDashboard
			a.views[command.ViewDashboard] = v

			a.Update(tea.BlurMsg{})
			if n := len(focusMsgsOf(v)); n != 0 {
				t.Errorf("run: a blur told the view %d times, want 0", n)
			}

			apply(a, policyConfig("")) // absent means pause
			v = &fakeView{}
			a.views[command.ViewDashboard] = v
			a.terminalBlurred = false
			a.Update(tea.BlurMsg{})
			if n := len(focusMsgsOf(v)); n != 1 {
				t.Errorf("pause: a blur told the view %d times, want 1", n)
			}
		})
	}
}

func TestRunPolicyBlurKeepsTheChainAlive(t *testing.T) {
	a, v := runPolicyRouter(t)
	startBlinkChain(t, a)

	a.Update(tea.BlurMsg{})
	cmd := tickAt(a, 1500)

	if _, ok := testutil.MsgOf[animationTickMsg](cmd); !ok {
		t.Error("run: the chain was not renewed while the terminal is blurred")
	}
	if !a.anim.ticking {
		t.Error("run: the router no longer believes a chain is alive")
	}
	if d, ok := a.wantedCadence(); !ok || d == 0 {
		t.Errorf("run: wantedCadence = (%v, %v) while blurred, want a cadence", d, ok)
	}
	if lastFrame(t, v).Blink {
		t.Error("run: the off phase was not handed to the view (animation is not suspended)")
	}
}

func TestRunPolicySendsNoFocusMessageOnEitherEdge(t *testing.T) {
	a, v := runPolicyRouter(t)

	a.Update(tea.BlurMsg{})
	a.Update(tea.FocusMsg{})

	if n := len(focusMsgsOf(&v.fakeView)); n != 0 {
		t.Errorf("run: views received %d TerminalFocusMsg, want none (nothing to resume)", n)
	}
}

func TestPausePolicyIsTheDefault(t *testing.T) {
	a, v, _ := blinkRouter(t, true)
	startBlinkChain(t, a)
	a.Update(tea.BlurMsg{})
	if _, ok := a.wantedCadence(); ok {
		t.Error("default policy: wantedCadence is wanted while blurred")
	}
	if n := len(focusMsgsOf(&v.fakeView)); n != 1 {
		t.Errorf("default policy: view told %d times, want 1", n)
	}
}

// Saving the setting while blurred applies at once.
func TestPauseToRunWhileBlurredResumesTheViewOnScreen(t *testing.T) {
	a, v, _ := blinkRouter(t, true)
	a.Update(tea.BlurMsg{})

	_ = a.applyWhenUnfocused(policyConfig(config.WhenUnfocusedRun))

	msgs := focusMsgsOf(&v.fakeView)
	if len(msgs) != 2 || msgs[1] != (shared.TerminalFocusMsg{Focused: true, Resume: true}) {
		t.Fatalf("view got %+v, want [blur, {Focused:true Resume:true}]", msgs)
	}
	if a.ensureTick() == nil {
		t.Error("pause -> run while blurred: no chain restarted")
	}
}

func TestRunToPauseWhileBlurredSuspendsAtOnce(t *testing.T) {
	a, v := runPolicyRouter(t)
	a.Update(tea.BlurMsg{})

	_ = a.applyWhenUnfocused(policyConfig(config.WhenUnfocusedPause))

	msgs := focusMsgsOf(&v.fakeView)
	if len(msgs) != 1 || msgs[0] != (shared.TerminalFocusMsg{Focused: false, Resume: false}) {
		t.Fatalf("view got %+v, want [{Focused:false Resume:false}]", msgs)
	}
	if _, ok := a.wantedCadence(); ok {
		t.Error("run -> pause while blurred: a chain is still wanted")
	}
}

func TestChangingThePolicyWhileFocusedTellsNobody(t *testing.T) {
	for _, to := range []string{config.WhenUnfocusedRun, config.WhenUnfocusedPause} {
		a, v, _ := blinkRouter(t, true)
		_ = a.applyWhenUnfocused(policyConfig(to))
		if n := len(focusMsgsOf(&v.fakeView)); n != 0 {
			t.Errorf("-> %s while focused: view told %d times, want 0", to, n)
		}
	}
}

func TestSaveWhileBlurredThroughConfigSavedMsg(t *testing.T) {
	a := router(t, &fakeView{})
	a.Update(tea.BlurMsg{})

	a.Update(configuration.ConfigSavedMsg{Config: policyConfig(config.WhenUnfocusedRun)})

	// handleConfigSaved rebuilt the views; whatever is on screen now is not
	// suspended, and the router no longer treats the blur as a pause.
	if _, ok := a.wantedCadence(); !ok && a.jobs.Running() > 0 {
		t.Error("run saved while blurred: running jobs get no cadence")
	}
	v := &blinkView{wants: true}
	a.views[command.ViewDashboard] = v
	if d, ok := a.wantedCadence(); !ok || d == 0 {
		t.Errorf("run saved while blurred: wantedCadence = (%v, %v), want a cadence", d, ok)
	}
}
package configuration

import (
	"strings"
	"testing"

	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/ui/testutil"
)

// DEVDESK-210 step 6: the "When unfocused" cycle field in the Appearance group.

func whenUnfocusedModel(t *testing.T, v string) Model {
	t.Helper()
	isolateMotionHome(t)
	m := newModel(t)
	m.config.App.WhenUnfocused = v
	return focusOn(t, m, whenUnfocusedLabel)
}

func TestWhenUnfocusedIsACycleFieldInTheAppearanceGroup(t *testing.T) {
	f := fieldNamed(t, whenUnfocusedLabel)

	if whenUnfocusedLabel != "When unfocused" {
		t.Errorf("whenUnfocusedLabel = %q, want When unfocused", whenUnfocusedLabel)
	}
	if f.Kind != kindCycle {
		t.Errorf("kind = %v, want kindCycle (Rule 132)", f.Kind)
	}
	if f.Group != fieldNamed(t, "Gauge glyph").Group {
		t.Errorf("group = %q, want the group of Gauge glyph (Appearance)", f.Group)
	}
	want := config.WhenUnfocusedModes()
	if strings.Join(f.Options, ",") != strings.Join(want, ",") {
		t.Errorf("options = %v, want %v", f.Options, want)
	}
}

func TestArrowsWriteWhenUnfocusedAndEmitConfigSavedMsg(t *testing.T) {
	for _, tt := range []struct {
		name, start, key, want string
	}{
		{"pause right", config.WhenUnfocusedPause, "right", config.WhenUnfocusedRun},
		{"run right wraps", config.WhenUnfocusedRun, "right", config.WhenUnfocusedPause},
		{"pause left wraps", config.WhenUnfocusedPause, "left", config.WhenUnfocusedRun},
		{"run left", config.WhenUnfocusedRun, "left", config.WhenUnfocusedPause},
	} {
		t.Run(tt.name, func(t *testing.T) {
			m := whenUnfocusedModel(t, tt.start)
			updated, cmd := m.Update(testutil.Key(tt.key))
			next := updated.(Model)

			if got := next.config.App.WhenUnfocused; got != tt.want {
				t.Fatalf("WhenUnfocused = %q, want %q", got, tt.want)
			}
			msg, ok := testutil.MsgOf[ConfigSavedMsg](cmd)
			if !ok {
				t.Fatal("no ConfigSavedMsg; the router never applies the new setting")
			}
			if msg.Config.App.WhenUnfocused != tt.want {
				t.Errorf("ConfigSavedMsg carries %q, want %q", msg.Config.App.WhenUnfocused, tt.want)
			}
		})
	}
}

func TestSpaceAndEnterDoNothingOnWhenUnfocused(t *testing.T) {
	for _, key := range []string{"space", "enter"} {
		t.Run(key, func(t *testing.T) {
			m := whenUnfocusedModel(t, config.WhenUnfocusedPause)
			updated, cmd := m.Update(testutil.Key(key))
			next := updated.(Model)

			if next.config.App.WhenUnfocused != config.WhenUnfocusedPause {
				t.Errorf("%s changed the setting to %q (Rule 135)", key, next.config.App.WhenUnfocused)
			}
			if _, ok := testutil.MsgOf[ConfigSavedMsg](cmd); ok {
				t.Errorf("%s saved the configuration", key)
			}
		})
	}
}

func TestAbsentWhenUnfocusedShowsTheDefaultAndStaysAbsent(t *testing.T) {
	m := whenUnfocusedModel(t, "")

	if got := fieldNamed(t, whenUnfocusedLabel).Value(m.config); got != "pause (default)" {
		t.Errorf("Value = %q, want %q", got, "pause (default)")
	}
	if !strings.Contains(plainRows(m), "pause (default)") {
		t.Error("the row does not read 'pause (default)'")
	}
	if m.config.App.WhenUnfocused != "" {
		t.Error("displaying the default wrote it")
	}

	next := feed(t, m, testutil.Key("right"))
	if next.config.App.WhenUnfocused != config.WhenUnfocusedRun {
		t.Fatalf("first → gave %q, want run", next.config.App.WhenUnfocused)
	}
	next = feed(t, next, testutil.Key("right"))
	if next.config.App.WhenUnfocused != config.WhenUnfocusedPause {
		t.Fatalf("second → gave %q, want an explicit pause", next.config.App.WhenUnfocused)
	}
	if got := fieldNamed(t, whenUnfocusedLabel).Value(next.config); got != "pause" {
		t.Errorf("explicit pause reads %q, want plain pause", got)
	}
}

