package app

import (
	"time"

	tea "charm.land/bubbletea/v2"

	"github.com/anthnel/devdesk/internal/command"
	"github.com/anthnel/devdesk/internal/shared"
)

// handleTerminalBlur records that the terminal lost the focus. Nothing else
// happens here: the live animation chain's in-flight tick reaches
// handleAnimationTick, wantedCadence says no, and the chain is not renewed
// (DEVDESK-210). No generation bump is needed. On the edge only, the view on
// screen is told.
func (a *App) handleTerminalBlur() (tea.Model, tea.Cmd) {
	if a.terminalBlurred {
		return a, nil
	}
	a.terminalBlurred = true
	return a, a.sendFocusTo(a.currentView, false)
}

// handleTerminalFocus clears the blur. A focus with no prior blur changes
// nothing (an unknown focus means focused) and tells nobody. After a blur, the
// view on screen is asked to resume. The Update wrapper's ensureTick restarts
// the one chain when something needs it.
func (a *App) handleTerminalFocus() (tea.Model, tea.Cmd) {
	if !a.terminalBlurred {
		return a, nil
	}
	a.terminalBlurred = false
	return a, a.sendFocusTo(a.currentView, true)
}

// sendFocusTo hands one view the terminal focus state. It never calls Init,
// starts no scan and sets no footer message; the view decides what to do with
// it. resume is true only when the focus comes back after a blur.
func (a *App) sendFocusTo(target command.ViewType, resume bool) tea.Cmd {
	view, ok := a.views[target]
	if !ok {
		return nil
	}
	updated, cmd := view.Update(shared.TerminalFocusMsg{Focused: !a.terminalBlurred, Resume: resume && !a.terminalBlurred})
	a.setView(target, updated)
	return cmd
}

// wantedCadence is cadence() for the router's current state: while the terminal
// is blurred no chain is wanted, whatever the views or the jobs ask for.
func (a *App) wantedCadence() (time.Duration, bool) {
	if a.terminalBlurred {
		return 0, false
	}
	return cadence(a.jobs.Running() > 0, a.wantsBlink(), a.motionStatic)
}
	// Navigation
	currentView command.ViewType
	views       map[command.ViewType]Screen
	sharedState *shared.State

	// terminalBlurred is set by tea.BlurMsg. The zero value means focused, so a
	// terminal without focus reporting behaves as before (DEVDESK-210).
	terminalBlurred bool

	commandMode  bool
	commandInput textinput.Model
	_ = sharedState.Forwards.SetProxyPort(cfg.Network.ProxyPort)

	app := &App{
		config:         cfg,
		currentContext: currentContext,
		viewport:       newViewport(width, height),
		currentView:    defaultView(cfg),
		views:          make(map[command.ViewType]Screen),
		sharedState:    sharedState,
		jobs:           jobs.New(),
		anim:           animationState{blinkOn: true},
		motionStatic:   cfg.App.StaticMotion(),
		commandInput:   newCommandInput(),
		suggester:      command.NewSuggester(),
		sugCursor:      -1,
		width:          width,
// The router asks the view on screen after every Update: a level, not an edge.
type BlinkingView interface {
	WantsBlink() bool
}

// Update is the router's only entry: the dispatch, then the level check of the
// animation chain. The view's own Cmd goes through untouched; ensureTick adds a
// Cmd only when a chain has to start or be replaced, and is idempotent, so a
// handler that already called it (jobsChanged) does not double the interval.
func (a *App) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	if _, ok := msg.(tea.FocusMsg); ok && !a.terminalBlurred {
		return a, nil // focus with no prior blur: nothing to do (DEVDESK-210)
	}
	model, cmd := a.update(msg)
	return model, tea.Batch(cmd, a.ensureTick())
}

// wantsBlink reports whether the view on screen has a row that blinks.
func (a *App) wantsBlink() bool {
	view, ok := a.views[a.currentView].(BlinkingView)
	return ok && view.WantsBlink()
}

// applyMotion points the animation at the motion a config asks for. It is
// called wherever the router takes a new config (context switch, every save);
// the constructor sets the field directly because it has no Cmd to return.
func (a *App) applyMotion(cfg *config.Config) tea.Cmd {
	return a.setMotionStatic(cfg.App.StaticMotion())
}

// setMotionStatic pins the blink phase on and stops blink-only chains. The view
// on screen is handed the pinned frame at once, otherwise it would keep an off
// phase until the next tick that may never come.
func (a *App) setMotionStatic(on bool) tea.Cmd {
	a.motionStatic = on
	if !on {
		return nil
	}
	a.anim.blinkOn = true
	return a.sendFrameTo(a.currentView)
}

func (a *App) update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		a.resize(msg.Width, msg.Height)
		return a, nil

	case tea.ColorProfileMsg:
		// Router state only (View sets the terminal background); not forwarded.
		a.colorProfile = msg.Profile
	}
	running := a.jobs.Running() > 0
	d, ok := a.wantedCadence()
	if !ok {
		a.anim.ticking = false
		// A blur always hands the view one last pinned frame: the tick that
		// lands after it is the last the view will see for a while.
		if a.anim.blinkOn && !a.terminalBlurred {
			return a, nil
		}
		a.anim.blinkOn = true
		return a, a.sendFrameTo(a.currentView)
	}
	// GaugeGlyph picks the fill of the load gauges: "shade" (default, `░` for
	// fill and track alike, told apart by colour) or "block" (`█` over a `░`
	// track). "block" is opt-in because `█` is East Asian ambiguous width and
	// overflows the gauge columns on a terminal that draws it double-width —
	// something only the user can know, which is why it is not guessed from
	// the locale (§3.71).
	GaugeGlyph string `yaml:"gauge_glyph"`

	// Motion picks whether activity indicators blink: "blink" (default) or
	// "static". An absent key stays absent and an unknown value is kept as
	// read (it behaves as blink, with a WARN at load) so a typo is not
	// silently rewritten.
	Motion string `yaml:"motion,omitempty"`
}

// Values app.gauge_glyph accepts.
const (
	GaugeGlyphShade = "shade"
	GaugeGlyphBlock = "block"
)

// GaugeGlyphs lists the values app.gauge_glyph names, safe default first.
func GaugeGlyphs() []string { return []string{GaugeGlyphShade, GaugeGlyphBlock} }

// Values app.motion accepts.
const (
	// cycles a closed set and a value outside it has nowhere to start from.
	if cfg.App.ContainerEngine == "" {
		cfg.App.ContainerEngine = EngineAuto
	}
	// Same reason: the configuration view cycles a closed set.
	if cfg.App.GaugeGlyph == "" {
		cfg.App.GaugeGlyph = GaugeGlyphShade
	}
	warnInvalidMotion(cfg.App)
	// Written rather than left empty for the reason above: the configuration
	// view cycles a closed set. A value outside it is left alone — remediation
	// reads it as same-line — so a typo in the file is not silently rewritten.
	if cfg.Scan.BaseImageTrack == "" {
		{Title: "app", Fields: slices.Concat(
			group("Appearance", theme.IconDashboard,
				cycle("Theme", func(c *config.Config) *string { return &c.App.Theme }, themes,
					"Applied as you cycle it"),
				cycle("Default view", func(c *config.Config) *string { return &c.App.DefaultView }, views,
					"The view DevDesk opens on"),
				cycle("Gauge glyph", func(c *config.Config) *string { return &c.App.GaugeGlyph },
					config.GaugeGlyphs(), "block fills with a solid █, which some terminals draw double-width"),
				cycleWithDefault(motionLabel, func(c *config.Config) *string { return &c.App.Motion },
					config.Motions(), config.DefaultMotion,
					"static keeps a running row's dot steady — no blinking, no periodic redraw"),
			),
			group("Paths", theme.IconDirectory,
				pathField("Workspaces dir", func(c *config.Config) *string { return &c.App.WorkspacesDir },
					"Root the workspaces view browses", filebrowser.PickDir),
				// Where the keystrokes land. It is the one path the user cannot
				// change from here, so it is shown rather than edited — and it
				Title: "Gauge glyph",
				Body: "shade (default) draws every gauge cell as ░ and tells fill from track by\n" +
					"colour. block fills with a solid █ over a ░ track, which keeps the bar\n" +
					"readable under the cursor. █ is drawn double-width by some terminals\n" +
					"(East Asian ambiguous width); if the gauge columns overflow, go back\n" +
					"to shade. It is not picked from your locale: only you know the terminal.",
			},
			{
				Title: "Motion",
				Body: "blink (default) makes a running row's dot " + indicator.Glyph(indicator.Running, true) + " blink once a\n" +
					"second. static keeps it a steady " + indicator.Glyph(indicator.Running, true) + ", same glyph and color,\n" +
					"with no periodic redraw. It is per context and applies as you cycle it.\n" +
					"A value in the file that is neither keeps blinking, and the footer says so.",
			},
			{
				Title: "Secret backend",
				Body: "Changing it is confirmed, and stored secrets are not migrated:\n" +
		// No credentials available — navigate to auth view for manual login
		a.currentView = command.ViewGitAuth
	}

	// The new context's tools may run from elsewhere: its views start from
	// "not known yet" rather than from the previous context's answer.
	a.forgetScanTools()

	// Reinitialize views with new config; auth state is already populated above
	initCmd := tea.Batch(a.reinitializeViews(), a.applyMotion(msg.Config))

	// The rebuilt views know nothing of the work that is still running, and it
	// did not stop: a run is stamped with the context it was started in and

	// Every view except this one is dropped so it is rebuilt against the saved
	// config on next use. Keeping the configuration view is what stops a save
	// from throwing away the cursor after every keystroke.
	current := a.views[command.ViewConfiguration]
	a.views = make(map[command.ViewType]Screen)
	if current != nil {
		a.setView(command.ViewConfiguration, current)
	}
	a.createView(a.currentView)
	motionCmd := a.applyMotion(msg.Config)

	return a, tea.Batch(a.requestResize(), a.syncProxyPortCmd(), a.redetectIfToolsMoved(msg.EngineChanged), motionCmd)
}

